# In ./nix/python-wasi.nix
{ fetchzip, stdenv }:

stdenv.mkDerivation {
  pname = "python-wasi";
  version = "3.11.4";

  src = fetchzip {
    url = "https://github.com/brettcannon/cpython-wasi-build/releases/download/v3.11.4/python-3.11.4-wasi_sdk-16.zip";
    stripRoot = false;
    sha256 = "sha256-AZGdgpRvHcu6FY/a7capldjDhTpkfhGkqYnm127nAN8=";
  };

  buildCommand = ''
   mkdir $out
   cp -r $src/* $out
  '';
}

# In ./flake.nix
utils.lib.eachDefaultSystem(system:
  let
    pkgs = import nixpkgs { inherit system; };
    python-wasi = pkgs.callPackage ./nix/python-wasi.nix {};
  in {

    devShells.default = pkgs.mkShell {
      name = "wasi";
      shellHook = ''
         export PYTHON_WASI=${python-wasi}
      '';
      packages = with pkgs; [ wasmtime ];
    };
  }
);

shellHook = ''
    export PYTHONHOME=${python-wasi}
''

utils.lib.eachDefaultSystem(system:
  let
    pkgs = import nixpkgs { inherit system; };
    python-wasi = pkgs.callPackage ./nix/python-wasi.nix {};
    python = pkgs.callPackage ./nix/python.nix { python-wasi = python-wasi; };
  in {

    devShells.default = pkgs.mkShell {
      name = "wasi";
      packages = [ python ];
    };
  }
 );

pyDeps = lib.concatMap (pkg: lib.remove pkg.pythonModule pkg.requiredPythonModules) pyPackages;
allPackages = lib.unique (pyPackages ++ pyDeps);
pythonPath = lib.concatMapStringsSep ":" (pkg: "${pkg}/lib/python3.11/site-packages") allPackages;

# In ./nix/python.nix

# Dependencies for our function (mostly) coming from `nixpkgs`
{ lib
, python-wasi
, mkShell
, stdenv
, wasmtime
, writeShellScriptBin
}:

# Arguments the user can set when invoking the function
{ pyPackages ? []
}:

# Implementation details
let
  pyDeps = lib.concatMap (pkg: lib.remove pkg.pythonModule pkg.requiredPythonModules) pyPackages;
  allPackages = lib.unique (pyPackages ++ pyDeps);
  pythonPath = lib.concatMapStringsSep ":" (pkg: "${pkg}/lib/python3.11/site-packages") allPackages;

  # This should look familiar...
  python = writeShellScriptBin "python" ''
   ${wasmtime}/bin/wasmtime run ${python-wasi}/python.wasm \
     --env PYTHONHOME=${python-wasi} \
     --env PYTHONPATH='.:${pythonPath}' \
     --dir ${python-wasi} \
     ${lib.concatMapStringsSep "\\\n  " (pkg: "--dir '${pkg}/lib/python3.11/site-packages' ") allPackages} \
     --dir . \
     -- "$@"
  '';

in
# Our function's return value
mkShell {
  name = "python-wasi";
  packages = [ python ];
}

pkgs = import nixpkgs { inherit system; };
python-wasi = pkgs.callPackage ./nix/python-wasi.nix {};
mkPythonWASIShell = pkgs.callPackage ./nix/python.nix { python-wasi = python-wasi; };

devShells.default = mkPythonWASIShell {
  pyPackages = with pkgs.python311Packages; [
    pygls
  ];
};

devShells = utils.lib.eachDefaultSystemMap (system:
    eachPythonVersion [ "38" "39" "310" "311" ] (pyVersion:
      with pkgs; mkShell {
        name = "py${pyVersion}";

        shellHook = ''
          export PYTHONPATH="./:$PYTHONPATH"
        '';

        packages = with pkgs."python${pyVersion}Packages"; [
          pygls
          pytest
          pytest-asyncio
        ];
      }
  )
);

devShells = utils.lib.eachDefaultSystemMap (system:
  applyMatrix buildMatrix ({ py, sphinx, ...}: {
    "py${py}-esbonio" = pkgs.mkShell { };          # A shell without sphinx avaialable at all
    "py${py}-sphinx${sphinx}" = pkgs.mkShell { };  # A shell containing the given sphinx verison
  })
);

$ nix repl
> buildMatrix = { py = [ "38" "39" "310" "311" ]; sphinx = [ "5" "6" "7" ]; }
> allCombinations = nixpkgs.lib.cartesianProductOfSets buildMatrix
> :p allCombinations  # ':p' Overrides nix's lazy evaluation to print the
                      # fully expanded version of an object
[
  { py = "38"; sphinx = "5"; }
  { py = "38"; sphinx = "6"; }
  { py = "38"; sphinx = "7"; }
  { py = "39"; sphinx = "5"; }
  { py = "39"; sphinx = "6"; }
  { py = "39"; sphinx = "7"; }
  { py = "310"; sphinx = "5"; }
  { py = "310"; sphinx = "6"; }
  { py = "310"; sphinx = "7"; }
  { py = "311"; sphinx = "5"; }
  { py = "311"; sphinx = "6"; }
  { py = "311"; sphinx = "7"; }
]

> shells = builtins.map ({py, sphinx}: {"py${py}-sphinx${sphinx}" = { }; }) allCombinations
> :p shells
[
  { py38-sphinx5 = { }; }
  { py38-sphinx6 = { }; }
  { py38-sphinx7 = { }; }
  { py39-sphinx5 = { }; }
  { py39-sphinx6 = { }; }
  { py39-sphinx7 = { }; }
  { py310-sphinx5 = { }; }
  { py310-sphinx6 = { }; }
  { py310-sphinx7 = { }; }
  { py311-sphinx5 = { }; }
  { py311-sphinx6 = { }; }
  { py311-sphinx7 = { }; }
]

> result = builtins.foldl' (x: y: x // y) {} shells
> :p result
{
  py310-sphinx5 = { };
  py310-sphinx6 = { };
  py310-sphinx7 = { };
  py311-sphinx5 = { };
  py311-sphinx6 = { };
  py311-sphinx7 = { };
  py38-sphinx5 = { };
  py38-sphinx6 = { };
  py38-sphinx7 = { };
  py39-sphinx5 = { };
  py39-sphinx6 = { };
  py39-sphinx7 = { };
}

applyMatrix = matrix: f:
  builtins.foldl' (x: y: x // y) {}
    (builtins.map f (nixpkgs.lib.cartesianProductOfSets matrix));

{
  description = "Esbonio";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixpkgs-unstable";
    utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, utils }:
    utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs { inherit system; };
      in {
        apps.default = { type = "app"; program = "${pkgs.neovim}/bin/nvim"; };
      }
    );
}

utils.lib.eachDefaultSystem (system:
   let
     pkgs = import nixpkgs { inherit system; };
     neovim = pkgs.neovim.override {
       configure = {
         customRC = ''
         '';
       };
     };
   in {
     apps.default = {
       type = "app";
       program = "${neovim}/bin/nvim";
     };
   }
 );

