let
  eachPythonVersion = ...
in

self: super:

eachPythonVersion [ "38" "39" "310" "311" ] (pyVersion:
  super."python${pyVersion}".override {
    packageOverrides = pyself: pysuper: {
      pytest-lsp = pysuper.buildPythonPackage { ... };
    };
})

# esbonio-overlay.nix
let
  eachPythonVersion = ...
in

self: super:

eachPythonVersion [ "38" "39" "310" "311" ] (pyVersion:
  super."python${pyVersion}".override {
    packageOverrides = pyself: pysuper: {
      esbonio = pysuper.buildPythonPackage { ... };
